"use client";

import { useEffect, useId, useState } from "react";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { CHART_THEMES } from "@/lib/chart-themes";
import { cn } from "@/lib/utils";
import {
  formatRadialValue,
  radialCeiling,
  summarizeRadialChart,
} from "@/features/radial-chart/radial-chart-schema";
import type { RadialChartData } from "@/features/radial-chart/radial-chart-schema";

export type RadialChartCardState = "streaming" | "loading" | "ready" | "error";

export interface RadialChartCardProperties {
  readonly state: RadialChartCardState;
  /**
  The topic from the tool input, shown before the data arrives.
  */
  readonly topic?: string;
  readonly data?: RadialChartData;
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-md`;

function titleCase(value: string) {
  return value
    .trim()
    .split(/\s+/u)
    .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(" ");
}

/**
The rings in chart units: the outermost ring's radius, each ring's thickness, and how far in the next one sits.
*/
const VIEW = 200;
const CENTER = VIEW / 2;
const OUTER_RADIUS = 86;
const RING = 11;
const RING_STEP = 16;
/**
A full ring runs three quarters of the way round, from twelve o'clock to nine, leaving the top-left quarter for the labels.
*/
const SWEEP = 75;
const HATCH_GAP = 3.5;

/**
With this many rings or fewer, the hole in the middle is big enough for the headline.
*/
const MAX_RINGS_WITH_CENTER = 3;

/**
How long each ring takes to draw, and how long it waits after the one outside it, so they wind up outside in.
*/
const DRAW_MS = 1000;
const RING_STAGGER_MS = 110;

/**
False for the first frame, so the rings start empty and their dash transition winds them up.
*/
function useIsDrawn() {
  const [isDrawn, setIsDrawn] = useState(false);
  useEffect(() => {
    const frame = requestAnimationFrame(() => setIsDrawn(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  return isDrawn;
}

function radiusOf(index: number) {
  return OUTER_RADIUS - index * RING_STEP;
}

/**
This card's colors: rose. Every chart card has its own, so a reply with several charts tells them apart at a glance.
*/
const THEME = CHART_THEMES.radial;

const Rings = ({ data }: { readonly data: RadialChartData }) => {
  const hatchId = useId();
  const isDrawn = useIsDrawn();
  const [active, setActive] = useState<number | null>(null);
  const ceiling = radialCeiling(data);
  const focusIndex = active ?? 0;
  const focus = data.rings[focusIndex];
  const hasCenter = data.rings.length <= MAX_RINGS_WITH_CENTER;

  return (
    <div className="relative mx-auto aspect-square w-full max-w-64">
      <svg
        aria-hidden
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className="size-full -rotate-90 overflow-visible"
      >
        <defs>
          {/* A pattern takes its color from where it is defined, not from the
              ring that uses it, so it carries the theme itself. */}
          <pattern
            id={hatchId}
            className={THEME.soft}
            width={HATCH_GAP}
            height={HATCH_GAP}
            patternUnits="userSpaceOnUse"
            patternTransform="rotate(45)"
          >
            <line
              x1={0}
              y1={0}
              x2={0}
              y2={HATCH_GAP}
              stroke="currentColor"
              strokeWidth={1.25}
            />
          </pattern>
        </defs>
        {data.rings.map((ring, index) => {
          const radius = radiusOf(index);
          const length = (Math.min(ring.value, ceiling) / ceiling) * SWEEP;
          const isLead = index === 0;
          const isActive = active === index;
          const isSolid = isLead || isActive;
          return (
            <g
              key={ring.name}
              className={cn(
                "transition-opacity duration-200",
                isLead ? THEME.solid : THEME.soft,
                active !== null && !isActive && "opacity-30"
              )}
              onMouseEnter={() => setActive(index)}
              onMouseLeave={() => setActive(null)}
            >
              <circle
                cx={CENTER}
                cy={CENTER}
                r={radius}
                fill="none"
                pathLength={100}
                className="stroke-muted"
                strokeWidth={RING}
                strokeDasharray={`${SWEEP} 100`}
                strokeLinecap="round"
              />
              {ring.value > 0 ? (
                <circle
                  cx={CENTER}
                  cy={CENTER}
                  r={radius}
                  fill="none"
                  pathLength={100}
                  stroke={isSolid ? "currentColor" : `url(#${hatchId})`}
                  strokeWidth={RING}
                  strokeDasharray={`${isDrawn ? length : 0} 100`}
                  strokeLinecap="round"
                  className="transition-[stroke-dasharray] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
                  style={{
                    transitionDelay: `${index * RING_STAGGER_MS}ms`,
                    transitionDuration: `${DRAW_MS}ms`,
                  }}
                />
              ) : null}
            </g>
          );
        })}
      </svg>

      {/* Each ring's name and value sit in the open quarter, ending just
          short of where the ring starts. */}
      <ol className="pointer-events-none absolute inset-0">
        {data.rings.map((ring, index) => (
          <li
            key={ring.name}
            className={cn(
              "absolute flex h-4 -translate-y-1/2 items-center justify-end gap-1.5 text-xs leading-4 transition-opacity duration-200",
              active !== null && active !== index && "opacity-30"
            )}
            style={{
              right: `${((CENTER + 8) / VIEW) * 100}%`,
              top: `${((CENTER - radiusOf(index)) / VIEW) * 100}%`,
            }}
          >
            <span
              className={cn(
                "max-w-20 truncate",
                index === 0 ? "font-semibold" : "text-muted-foreground"
              )}
            >
              {ring.name}
            </span>
            <span className="font-mono font-medium tabular-nums">
              {formatRadialValue(ring.value, data.scale)}
            </span>
          </li>
        ))}
      </ol>

      {hasCenter && focus ? (
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center"
        >
          <p className="font-mono text-2xl leading-8 font-semibold tracking-tighter tabular-nums">
            {formatRadialValue(focus.value, data.scale)}
          </p>
          <p className="text-muted-foreground max-w-24 truncate text-xs">
            {focus.name}
          </p>
        </div>
      ) : null}
    </div>
  );
};

/**
"of 500K" when a full ring is a target rather than the obvious 100%, so the reader knows what full means.
*/
function fullMark(data: RadialChartData) {
  const isObvious =
    data.max === null || (data.scale === "percent" && data.max === 100);
  return isObvious
    ? null
    : `of ${formatRadialValue(radialCeiling(data), data.scale)}`;
}

const RadialChartReady = ({ data }: { readonly data: RadialChartData }) => {
  const mark = fullMark(data);
  return (
    <div className="flex flex-col gap-3">
      <header className="flex h-5 min-w-0 items-center">
        <p className="truncate text-sm font-semibold">
          {titleCase(data.topic)}
        </p>
      </header>

      <div className="py-1">
        <Rings data={data} />
      </div>

      <footer className="flex items-center justify-between gap-2">
        <p className="text-muted-foreground min-w-0 truncate text-xs">
          {data.label}
          {mark ? (
            <>
              {" "}
              <span className="font-mono tabular-nums">{mark}</span>
            </>
          ) : null}
          {data.period ? (
            <>
              {" · "}
              <span className="tabular-nums">{data.period}</span>
            </>
          ) : null}
        </p>
      </footer>
    </div>
  );
};

const RadialChartError = ({
  topic,
  message = "The figures service didn't respond. Try again in a moment.",
}: {
  readonly topic?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {topic
        ? `Couldn't load the figures for ${titleCase(topic)}`
        : "Couldn't load the radial chart"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

const SKELETON_RINGS = 4;

/**
The card while its data is on the way: empty tracks the size of the ready rings, so the card holds its place while the figures are found. Shows the topic as soon as it's known (with "…" while the model is still writing it).
*/
export const RadialChartCardSkeleton = ({
  topic,
  streaming = false,
  className,
}: {
  readonly topic?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "flex flex-col gap-3", className)}>
    <span className="sr-only">
      {topic ? `Loading the figures for ${topic}` : "Loading a radial chart"}
    </span>
    <div aria-hidden className="flex h-5 items-center">
      {topic ? (
        <p className="truncate text-sm font-semibold">
          {titleCase(topic)}
          {streaming ? <span className="text-muted-foreground">…</span> : null}
        </p>
      ) : (
        <div className="bg-muted h-3.5 w-24 animate-pulse rounded" />
      )}
    </div>
    <div aria-hidden className="py-1">
      <svg
        aria-hidden
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className="mx-auto aspect-square w-full max-w-64 -rotate-90 animate-pulse"
      >
        {Array.from({ length: SKELETON_RINGS }, (_, index) => (
          <circle
            // The tracks are identical placeholders with nothing else to key on.
            key={index}
            cx={CENTER}
            cy={CENTER}
            r={radiusOf(index)}
            fill="none"
            pathLength={100}
            className="stroke-muted"
            strokeWidth={RING}
            strokeDasharray={`${SWEEP} 100`}
            strokeLinecap="round"
          />
        ))}
      </svg>
    </div>
    <div aria-hidden className="flex h-4 items-center">
      <div className="bg-muted h-3 w-28 animate-pulse rounded" />
    </div>
  </output>
);

export const RadialChartCard = ({
  state,
  topic,
  data,
  error,
  className,
}: RadialChartCardProperties) => {
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <RadialChartError topic={topic} message={error} />
      </div>
    );
  }
  if (state !== "ready" || !data) {
    return (
      <RadialChartCardSkeleton
        topic={topic}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  return (
    <section
      aria-label={summarizeRadialChart(data)}
      className={cn(CARD_FRAME, className)}
    >
      <RadialChartReady data={data} />
    </section>
  );
};

"use client";

import { useEffect, useState } from "react";
import { RadialChartCard } from "@/features/radial-chart/components/radial-chart-card";
import { loadRadialChart } from "@/features/radial-chart/radial-chart-requests";
import type { RadialChartData } from "@/features/radial-chart/radial-chart-schema";

/**
What came back for one request. A result for a different topic reads as still loading, so a new topic never flashes the old chart.
*/
type Result =
  | { key: string; status: "ready"; data: RadialChartData }
  | { key: string; status: "error"; message: string };

export const LiveRadialChartCard = ({
  topic,
  streaming = false,
}: {
  readonly topic?: string;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [result, setResult] = useState<Result | null>(null);
  const requestKey = topic ?? "";

  useEffect(() => {
    let isCancelled = false;
    const run = async (wanted: string) => {
      let next: Result;
      try {
        next = {
          data: await loadRadialChart(wanted),
          key: requestKey,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: requestKey,
          message: Error.isError(error)
            ? error.message
            : "Radial chart failed.",
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && topic) {
      run(topic);
    }
    return () => {
      isCancelled = true;
    };
  }, [topic, requestKey, streaming]);

  if (streaming || !topic) {
    return <RadialChartCard state="streaming" topic={topic} />;
  }
  const current = result?.key === requestKey ? result : null;
  if (current?.status === "ready") {
    return <RadialChartCard state="ready" data={current.data} />;
  }
  return current?.status === "error" ? (
    <RadialChartCard state="error" topic={topic} error={current.message} />
  ) : (
    <RadialChartCard state="loading" topic={topic} />
  );
};

import { z } from "zod";

export const radialChartCatalogEntry = {
  description: `A live radial chart for questions about how full or how far along a few items are against the same mark ("how full are California's reservoirs?", "what share of electricity is renewable in Germany, the UK and the US?", "what percent of US adults use each social platform?"). Each item is one ring, a full ring being the mark (100%, capacity, a target). The model writes a free-text topic from the user's ask; the card researches the web and draws the rings, the largest outermost. The topic is the card's title, so keep it a short phrase naming the measure and the items ("California reservoir levels"). Never invent the numbers — the card fetches them. Not for parts of one whole: that's PieChartCard. Not for many categories: that's BarChartCard.`,
  props: z.object({
    topic: z
      .string()
      .describe(
        'The measure and the items, taken from the user\'s question — e.g. "California reservoir levels" or "renewable share of electricity in Germany, the UK and the US".'
      ),
  }),
};

import type { RadialChartData } from "@/features/radial-chart/radial-chart-schema";

const sharedRadialChartRequests = new Map<
  string,
  { chart: Promise<RadialChartData>; expiresAt: number }
>();
const REUSE_MS = 120_000;

function cacheKey(topic: string) {
  return topic.trim().toLowerCase();
}

function radialChartUrl(topic: string) {
  const parameters = new URLSearchParams({ topic });
  return `/api/radial-chart?${parameters}`;
}

async function fetchRadialChart(topic: string) {
  const response = await fetch(radialChartUrl(topic));
  const body = (await response.json()) as RadialChartData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Radial chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestRadialChart(key: string, topic: string) {
  try {
    return await fetchRadialChart(topic);
  } catch (error) {
    sharedRadialChartRequests.delete(key);
    throw error;
  }
}

/**
Load a radial chart's figures. Shared, so the thinking steps and the card make one request between them.
*/
export function loadRadialChart(topic: string) {
  const key = cacheKey(topic);
  const hit = sharedRadialChartRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.chart;
  }
  const chart = requestRadialChart(key, topic);
  sharedRadialChartRequests.set(key, {
    chart,
    expiresAt: Date.now() + REUSE_MS,
  });
  return chart;
}

/**
Seed the client cache from a docs recording.
*/
export function primeRadialChart(topic: string, data: RadialChartData) {
  sharedRadialChartRequests.set(cacheKey(topic), {
    chart: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import { listOf } from "@/features/chat/lookup";
import { loadRadialChart } from "@/features/radial-chart/radial-chart-requests";
import { hostOf } from "@/lib/url-host";
import type { CardLookup, Source } from "@/features/chat/lookup";

function topicOf(properties: Record<string, unknown>): string {
  return typeof properties.topic === "string" ? properties.topic.trim() : "";
}

function researchSources(result: unknown): readonly Source[] {
  if (!result || typeof result !== "object") {
    return [];
  }
  const { sourceHref, sourceLabel } = result as {
    sourceHref?: unknown;
    sourceLabel?: unknown;
  };
  if (typeof sourceHref !== "string" || !sourceHref) {
    return [];
  }
  const label =
    typeof sourceLabel === "string" && sourceLabel.trim()
      ? sourceLabel.trim()
      : hostOf(sourceHref);
  return [{ href: sourceHref, label }];
}

export const radialChartLookup: CardLookup = {
  intent: (topics) =>
    topics.length === 1
      ? `The figures for ${topics[0]}`
      : `The figures for ${listOf(topics)}`,
  load: (properties) => {
    const topic = topicOf(properties);
    return topic
      ? loadRadialChart(topic)
      : Promise.reject(
          new Error('Pass a topic, for example "California reservoir levels".')
        );
  },
  resultSources: researchSources,
  sources: () => [
    {
      href: "https://parallel.ai",
      label: "parallel.ai",
    },
  ],
  subject: (properties) => topicOf(properties) || null,
};

import "server-only";
import {
  createExtractTool,
  createSearchTool,
} from "@parallel-web/ai-sdk-tools";
import { generateText, isStepCount, Output } from "ai";
import {
  MAX_RINGS,
  MIN_RINGS,
  radialChartResultSchema,
} from "@/features/radial-chart/radial-chart-schema";
import type {
  RadialChartData,
  RadialChartResult,
  RadialRing,
} from "@/features/radial-chart/radial-chart-schema";

/**
Research copies data tables into numbers, so it uses the same model as the other charts' research, separate from the chat model.
*/
const DEFAULT_RESEARCH_MODEL = "anthropic/claude-haiku-5.5";

/**
Tool steps before the model must answer. Step 0 is forced to search and step 1 to extract, so the numbers come from a page rather than memory; without a forced final answer the model keeps digging and returns nothing.
*/
const STEPS = 5;
const TIMEOUT_MS = 55_000;
/**
Parallel serves cached pages by default; an extracted page older than a day is fetched live so a table's newest release isn't missed.
*/
const LIVE_FETCH_MAX_AGE_S = 86_400;

export class RadialChartNotFoundError extends Error {
  constructor(topic: string, options?: ErrorOptions) {
    super(`No radial chart figures found for "${topic}".`, options);
    this.name = "RadialChartNotFoundError";
  }
}

function researchPrompt(topic: string): string {
  const today = new Date();
  const year = today.getUTCFullYear();

  return `Today is ${today.toISOString().slice(0, 10)}. Find real public figures for a few items measured against the same full mark, for a radial chart (one ring per item, a full ring being the mark):

Topic: ${topic}

Requirements:
- ${MIN_RINGS}–${MAX_RINGS} items in one unit, each a level against a natural full mark: reservoirs as percent of capacity, renewable share of electricity by country, adoption rates, progress toward a target.
- max: the value of a full ring — 100 for shares and percent of capacity, the target when there is one, otherwise null.
- Prefer official or well-known sources (state water agencies, Ember, IEA, Pew Research, national statistics offices).
- Search first, then extract the best URL(s) — a data table, CSV or JSON API, not an article — and copy the numbers from it.
- The latest figures, ${year - 1} or ${year} (or today's reading for live levels). Say which period in period.
- When the topic doesn't name the items, pick the ${MAX_RINGS} a reader would check first (the largest reservoirs, the biggest economies).
- Non-negative numeric values only, written out in full.
- scale: "percent" for rates and shares, "currency" for money in USD, otherwise "number".
- You have ${STEPS} tool steps, then you must answer from what you extracted.
- If the topic can't be measured this way, fail rather than inventing figures.`;
}

function cleanRings(rings: RadialChartResult["rings"]): RadialRing[] {
  const seen = new Set<string>();
  const cleaned: RadialRing[] = [];
  for (const ring of rings) {
    const name = ring.name.trim();
    if (
      !name ||
      !Number.isFinite(ring.value) ||
      ring.value < 0 ||
      seen.has(name.toLowerCase())
    ) {
      continue;
    }
    seen.add(name.toLowerCase());
    cleaned.push({ name, value: ring.value });
  }
  return cleaned.toSorted((a, b) => b.value - a.value).slice(0, MAX_RINGS);
}

function toRadialChartData(
  query: string,
  output: RadialChartResult
): RadialChartData {
  const rings = cleanRings(output.rings);
  if (rings.length < MIN_RINGS) {
    throw new RadialChartNotFoundError(query);
  }
  return {
    asOf: Date.now(),
    fake: false,
    label: output.label.trim() || "Value",
    max: output.max && output.max > 0 ? output.max : null,
    period: output.period?.trim() || null,
    rings,
    scale: output.scale,
    sourceHref: output.sourceHref ?? undefined,
    sourceLabel: output.sourceLabel ?? undefined,
    topic: query,
  };
}

async function researchOnce(
  query: string,
  abortSignal: AbortSignal
): Promise<RadialChartData> {
  const model = process.env.RADIAL_CHART_MODEL || DEFAULT_RESEARCH_MODEL;
  const webSearch = createSearchTool({
    client_model: model,
    max_results: 8,
    mode: "advanced",
  });
  const webExtract = createExtractTool({
    client_model: model,
    fetch_policy: { max_age_seconds: LIVE_FETCH_MAX_AGE_S },
  });

  const { output } = await generateText({
    abortSignal,
    instructions:
      "You turn questions into honest progress figures, a few items each measured against the same full mark, for a generative UI radial chart. Never invent, estimate or recall figures from memory: every value must come from a page you extracted.",
    model,
    output: Output.object({ schema: radialChartResultSchema }),
    prepareStep: ({ stepNumber }) => {
      if (stepNumber === 0) {
        return { toolChoice: { toolName: "webSearch", type: "tool" } };
      }
      if (stepNumber === 1) {
        return { toolChoice: { toolName: "webExtract", type: "tool" } };
      }
      return stepNumber >= STEPS ? { toolChoice: "none" } : {};
    },
    prompt: researchPrompt(query),
    stopWhen: isStepCount(STEPS + 1),
    tools: {
      webExtract,
      webSearch,
    },
  });

  if (!output?.rings?.length) {
    throw new RadialChartNotFoundError(query);
  }
  return toRadialChartData(query, output);
}

async function researchRadialChart(query: string): Promise<RadialChartData> {
  const abortSignal = AbortSignal.timeout(TIMEOUT_MS);
  try {
    return await researchOnce(query, abortSignal);
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
    return await researchOnce(query, abortSignal);
  }
}

/**
Research a free-text topic on the web (Parallel search + extract) and shape it into a few items measured against the same full mark.
*/
export async function getRadialChart(topic: string): Promise<RadialChartData> {
  const query = topic.trim();
  if (!query) {
    throw new RadialChartNotFoundError(topic);
  }
  if (!process.env.PARALLEL_API_KEY) {
    throw new Error(
      "PARALLEL_API_KEY is missing. Add it to .env.local to load live radial charts."
    );
  }

  try {
    return await researchRadialChart(query);
  } catch (error) {
    if (error instanceof RadialChartNotFoundError) {
      throw error;
    }
    if (Error.isError(error) && /PARALLEL_API_KEY/u.test(error.message)) {
      throw error;
    }
    throw new RadialChartNotFoundError(query, { cause: error });
  }
}

import { z } from "zod";

export const RADIAL_CHART_SCALES = ["number", "percent", "currency"] as const;
export type RadialChartScale = (typeof RADIAL_CHART_SCALES)[number];

/**
Fewest and most rings. One ring is a gauge, not a comparison; past five the inner rings get too short to read.
*/
export const MIN_RINGS = 2;
export const MAX_RINGS = 5;

export interface RadialRing {
  /**
  What the ring measures, e.g. "Shasta" or "Germany".
  */
  name: string;
  value: number;
}

export interface RadialChartData {
  /**
  The free-text topic the model (or caller) asked for.
  */
  topic: string;
  /**
  What the values measure, e.g. "Percent of capacity" or "Renewable share".
  */
  label: string;
  scale: RadialChartScale;
  /**
  The value of a full ring: 100 for a share, a capacity or a target, or null to fit the largest value.
  */
  max: number | null;
  /**
  Biggest first, so the outer (longest) ring leads.
  */
  rings: RadialRing[];
  /**
  The period the figures are for, e.g. "2025" or "Oct 18, 2026".
  */
  period: string | null;
  /**
  Unix time in milliseconds of when the figures were looked up.
  */
  asOf: number;
  /**
  True when this is generated data, not live figures.
  */
  fake: boolean;
  /**
  Optional attribution for thinking-step sources.
  */
  sourceHref?: string;
  sourceLabel?: string;
}

/**
Structured answer the research model must return after searching the web.
*/
export const radialChartResultSchema = z.object({
  label: z
    .string()
    .describe(
      'What the values measure in 2–5 words, e.g. "Percent of capacity" or "Renewable share". No sources, places or notes: the title has those.'
    ),
  max: z
    .number()
    .nullable()
    .describe(
      "The value of a full ring: 100 for shares and percent of capacity, the target when there is one, otherwise null."
    ),
  period: z
    .string()
    .nullable()
    .describe(
      'The period the figures are for, short, e.g. "2025", "Jun 2026" or "Oct 18, 2026", or null.'
    ),
  rings: z
    .array(
      z.object({
        name: z
          .string()
          .describe('A short name, 1–3 words, e.g. "Shasta" or "Germany".'),
        value: z.number(),
      })
    )
    .min(MIN_RINGS)
    .describe(
      `The items, ${MIN_RINGS}–${MAX_RINGS}. Non-negative numbers only, written out in full.`
    ),
  scale: z
    .enum(RADIAL_CHART_SCALES)
    .describe(
      "percent for rates and shares, currency for money in USD, otherwise number."
    ),
  sourceHref: z
    .string()
    .nullable()
    .describe("Best source URL for the numbers, or null."),
  sourceLabel: z
    .string()
    .nullable()
    .describe("Short source name, e.g. California DWR or Ember."),
});
export type RadialChartResult = z.infer<typeof radialChartResultSchema>;

/**
The value of a full ring: the given max when nothing goes past it, otherwise the largest value, so the leader closes its ring.
*/
export function radialCeiling(data: RadialChartData): number {
  const largest = Math.max(0, ...data.rings.map((ring) => ring.value));
  return data.max && data.max >= largest ? data.max : largest || 1;
}

function formatCurrency(value: number): string {
  const formatter = new Intl.NumberFormat("en-US", {
    currency: "USD",
    maximumFractionDigits: 0,
    style: "currency",
  });
  return formatter.format(value);
}

function formatPlain(value: number, maximumFractionDigits: number): string {
  const formatter = new Intl.NumberFormat("en-US", { maximumFractionDigits });
  return formatter.format(value);
}

function numberFractionDigits(absolute: number): number {
  if (absolute >= 100) {
    return 0;
  }
  return absolute >= 10 ? 1 : 2;
}

const MAGNITUDES = [
  { divisor: 1_000_000_000_000, suffix: "T" },
  { divisor: 1_000_000_000, suffix: "B" },
  { divisor: 1_000_000, suffix: "M" },
  { divisor: 1000, suffix: "K" },
] as const;

/**
Values above this read better as "12.3K" than "12,345" beside a ring.
*/
const COMPACT_THOUSANDS_FROM = 100_000;

function compactMagnitude(absolute: number) {
  return MAGNITUDES.find(
    ({ divisor }) =>
      absolute >= divisor &&
      (divisor > 1000 || absolute >= COMPACT_THOUSANDS_FROM)
  );
}

const DECIMAL = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });

export function formatRadialValue(
  value: number,
  scale: RadialChartScale,
  isCompact = true
): string {
  if (scale === "percent") {
    return `${DECIMAL.format(value)}%`;
  }
  const absolute = Math.abs(value);
  const magnitude = isCompact ? compactMagnitude(absolute) : undefined;
  if (!magnitude) {
    return scale === "currency"
      ? formatCurrency(value)
      : formatPlain(value, numberFractionDigits(absolute));
  }
  const scaled = value / magnitude.divisor;
  const digits = Math.abs(scaled) >= 100 ? 0 : 1;
  return `${scale === "currency" ? "$" : ""}${scaled.toFixed(digits)}${magnitude.suffix}`;
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeRadialChart(data: RadialChartData): string {
  const ceiling = radialCeiling(data);
  const rings = data.rings.map(
    (ring) => `${ring.name} ${formatRadialValue(ring.value, data.scale, false)}`
  );
  return `${data.label}, out of ${formatRadialValue(ceiling, data.scale, false)}: ${rings.join(", ")}.`;
}

